module.exports = function(RED) {
    "use strict";

    function SocialServiceNode(config) {
        RED.nodes.createNode(this, config);
        var node = this;
        node.resourceType = config.resourceType;
        node.socialResource = config.socialResource;
        node.func = config.func;

        this.on("input", function(msg, send, done) {
            msg.resourceType = node.resourceType;
            msg.socialResource = node.socialResource;
            msg.func = node.func; // 这里就是 url

            send(msg);
            if (done) {
                done();
            }
        });
    }

    RED.nodes.registerType("Social Service", SocialServiceNode);
};